sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') return;

    var baseValidator = new GlideAjax("x_2060759_base_m_0.BaseValidatorUtils");
    baseValidator.addParam("sysparm_name",    "checkDuplicateManager");
    baseValidator.addParam("sysparm_manager", newValue);

    baseValidator.getXMLAnswer(function(response) {
        if (response === 'true') {
            g_form.addErrorMessage("This manager is already managing another base.");
            g_form.clearValue("manager");
        } else {
            g_form.clearMessages();
        }
    });
}
